421	async function runSetupFlow(key?: string, scopeGlobal = false) {
422	  if (key) {
423	    await configureApiKeyIfProvided(key, scopeGlobal);
424	    return;
425	  }
426	
427	  if (!scopeGlobal) {
428	    const { scope } = await inquirer.prompt<{ scope: 'local' | 'global' }>([
429	      {
430	        type: 'list',
431	        name: 'scope',
432	        message: 'Where should we store the OpenAI API key?',
433	        choices: [
434	          { name: `Local project (${LOCAL_ENV_DISPLAY})`, value: 'local' },
435	          { name: `Global config (${GLOBAL_CONFIG_DISPLAY})`, value: 'global' }
436	        ],
437	        default: 'local'
438	      }
439	    ]);
440	    scopeGlobal = scope === 'global';
441	  }
442	
443	  await promptForApiKey(scopeGlobal);
444	}
