function assertFileExists(targetPath: string) {
  if (!fs.existsSync(targetPath)) {
    throw new Error(`File not found: ${targetPath}`);
  }
}

function parseThresholds(thresholdStrings?: string[]) {
  if (!thresholdStrings || thresholdStrings.length === 0) {
    return null;
  }

  const thresholds: Record<string, number> = {};

  for (const thresholdStr of thresholdStrings) {
    const match = thresholdStr.match(/^([a-z_]+)=([0-9.]+)$/);
    if (!match) {
      throw new Error(`Malformed threshold: "${thresholdStr}". Expected format: metric=0.9`);
    }

    const [, metricId, scoreStr] = match;
    const score = parseFloat(scoreStr);

    if (Number.isNaN(score) || score < 0 || score > 1) {
      throw new Error(`Invalid threshold value for ${metricId}: ${scoreStr}. Must be a number between 0 and 1.`);
    }

    thresholds[metricId] = score;
  }

  return thresholds;
}

function runEvalCommand(options: EvalOptions) {
  assertFileExists(options.outputs);
  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
    outputsPath: options.outputs,
    referencesPath: options.references
  });
  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
    outputs: dataset.outputs,
    references: dataset.references
  });

  let thresholds: Record<string, number> | null = null;
  try {
    thresholds = parseThresholds(options.threshold);
  } catch (error) {
    log.error((error as Error).message);
    const validMetrics = (Eval.DEFAULT_METRICS as unknown as Array<{ id?: string } | ((...args: any[]) => { id?: string })>)
      .map((metric) => {
        if (typeof metric === 'function') {
          const result = metric([], []);
          return result.id;
        }
        return metric.id;
      })
      .filter(Boolean);
    log.error(`Valid metric IDs: ${validMetrics.join(', ')}`);
    process.exit(2);
  }

  let report: any;
  try {
    report = (Eval.generateReport as unknown as (config: unknown) => any)({
      evaluations,
      outputsPath: dataset.outputsPath,
      referencesPath: dataset.referencesPath,
      thresholds
    });
  } catch (error) {
    const errorMessage = (error as Error).message;
    if (errorMessage.startsWith('Unknown metric:')) {
      log.error(errorMessage);
      const validMetrics = (Eval.DEFAULT_METRICS as unknown as Array<{ id?: string } | ((...args: any[]) => { id?: string })>)
        .map((metric) => {
          if (typeof metric === 'function') {
            const result = metric([], []);
            return result.id;
          }
          return metric.id;
        })
        .filter(Boolean);
      log.error(`Valid metric IDs: ${validMetrics.join(', ')}`);
      process.exit(2);
    }
    throw error;
  }

  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
    report,
    format: options.format ?? 'json',
    reportPath: options.report
  });
  log.success('Evaluation report generated.', { path: resolvedPath });

  if (report.passed === false) {
    log.error('Threshold validation failed.');
    process.exit(1);
  }
}

