478	  if (!thresholdStrings || thresholdStrings.length === 0) {
479	    return null;
480	  }
481	
482	  const thresholds: Record<string, number> = {};
483	
484	  for (const thresholdStr of thresholdStrings) {
485	    const match = thresholdStr.match(/^([a-z_]+)=([0-9.]+)$/);
486	    if (!match) {
487	      throw new Error(`Malformed threshold: "${thresholdStr}". Expected format: metric=0.9`);
488	    }
489	
490	    const [, metricId, scoreStr] = match;
491	    const score = parseFloat(scoreStr);
492	
493	    if (Number.isNaN(score) || score < 0 || score > 1) {
494	      throw new Error(`Invalid threshold value for ${metricId}: ${scoreStr}. Must be a number between 0 and 1.`);
495	    }
496	
497	    thresholds[metricId] = score;
498	  }
499	
500	  return thresholds;
501	}
