503	function runEvalCommand(options: EvalOptions) {
504	  assertFileExists(options.outputs);
505	  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
506	    outputsPath: options.outputs,
507	    referencesPath: options.references
508	  });
509	  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
510	    outputs: dataset.outputs,
511	    references: dataset.references
512	  });
513	
514	  let thresholds: Record<string, number> | null = null;
515	  try {
516	    thresholds = parseThresholds(options.threshold);
517	  } catch (error) {
518	    log.error((error as Error).message);
519	    const validMetrics = (Eval.DEFAULT_METRICS as unknown as Array<{ id?: string } | ((...args: any[]) => { id?: string })>)
520	      .map((metric) => {
521	        if (typeof metric === 'function') {
522	          const result = metric([], []);
523	          return result.id;
524	        }
525	        return metric.id;
526	      })
527	      .filter(Boolean);
528	    log.error(`Valid metric IDs: ${validMetrics.join(', ')}`);
529	    process.exit(2);
530	  }
531	
532	  let report: any;
533	  try {
534	    report = (Eval.generateReport as unknown as (config: unknown) => any)({
535	      evaluations,
536	      outputsPath: dataset.outputsPath,
537	      referencesPath: dataset.referencesPath,
538	      thresholds
539	    });
540	  } catch (error) {
541	    const errorMessage = (error as Error).message;
542	    if (errorMessage.startsWith('Unknown metric:')) {
