  it('generates and writes report', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z'
    });
    expect(report.metadata.totalSamples).toBe(1);

    const dir = createTempDir();
    const jsonPath = writeReport({
      report,
      format: 'json',
      reportPath: path.join(dir, 'report.json')
    });
    const markdownPath = writeReport({
      report,
      format: 'markdown',
      reportPath: path.join(dir, 'report.md')
    });

    expect(fs.existsSync(jsonPath)).toBe(true);
    expect(fs.existsSync(markdownPath)).toBe(true);
  });

  it('generates report with passing thresholds', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: {
        exact_match: 0.9,
        toxicity: 0.5
      },
      generatedAt: '2024-01-01T00:00:00.000Z'
    });

    expect(report.passed).toBe(true);
    expect(report.thresholds).toHaveLength(2);
    expect(report.thresholds[0]).toEqual({
      metric: 'exact_match',
      min: 0.9,
      score: 1,
      passed: true
    });
  });

  it('generates report with failing thresholds', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'Goodbye'],
      references: ['hello', 'world']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: {
        exact_match: 0.9
      },
      generatedAt: '2024-01-01T00:00:00.000Z'
    });

    expect(report.passed).toBe(false);
    expect(report.thresholds).toHaveLength(1);
    expect(report.thresholds[0].passed).toBe(false);
  });

  it('fails threshold when metric score is null', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: []
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: null,
      thresholds: {
        exact_match: 0.5
      },
      generatedAt: '2024-01-01T00:00:00.000Z'
    });

    expect(report.passed).toBe(false);
    expect(report.thresholds[0].passed).toBe(false);
  });

  it('throws error for unknown metric in thresholds', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });

    expect(() => {
      generateReport({
        evaluations,
        outputsPath: '/tmp/outputs.json',
        referencesPath: '/tmp/refs.json',
        thresholds: {
          unknown_metric: 0.5
        },
        generatedAt: '2024-01-01T00:00:00.000Z'
      });
    }).toThrow('Unknown metric: unknown_metric');
  });

  it('writes markdown report with thresholds section', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: {
        exact_match: 0.9
      },
      generatedAt: '2024-01-01T00:00:00.000Z'
    });

    const dir = createTempDir();
    const markdownPath = writeReport({
      report,
      format: 'markdown',
      reportPath: path.join(dir, 'report.md')
    });

    const content = fs.readFileSync(markdownPath, 'utf8');
    expect(content).toContain('## Thresholds');
    expect(content).toContain('exact_match');
    expect(content).toContain('PASS');
  });
});
